insert into public.trainers (slug, name, business_name, headline, bio, city, region, postcode_district, location, in_person, online, home_visits, price_from, price_to, qualifications, years_experience, website, email, phone, instagram, image_url, free_consultation, sports, source, source_url, source_licence, last_verified_at, is_sample, status)
select 'sculpt-yoga-and-pilates-barnsley', 'Sally Akers', 'Sculpt Yoga and Pilates', 'Pilates, reformer, yoga and PT', 'Sally Akers runs Sculpt Yoga and Pilates in Barnsley, teaching mat Pilates, chair Pilates, yoga, body sculpt and Gravity reformer classes, plus personal training for every age and ability.', 'Barnsley', 'South Yorkshire', 'S70', extensions.st_setsrid(extensions.st_makepoint(-1.4747, 53.541), 4326)::extensions.geography, true, false, false, null, null, '{}'::text[], null, 'https://www.sculptyogaandpilates.co.uk/', null, null, null, null, false, '{}'::text[], 'website', 'https://www.sculptyogaandpilates.co.uk/', 'Business details published on the trainer''s own website', now(), false, 'published'
where not exists (select 1 from public.trainers where slug = 'sculpt-yoga-and-pilates-barnsley' and status = 'removed')
on conflict (slug) do update set name = excluded.name, business_name = excluded.business_name, headline = excluded.headline, bio = excluded.bio, city = excluded.city, region = excluded.region, postcode_district = excluded.postcode_district, location = excluded.location, in_person = excluded.in_person, online = excluded.online, home_visits = excluded.home_visits, price_from = excluded.price_from, price_to = excluded.price_to, qualifications = excluded.qualifications, years_experience = excluded.years_experience, website = excluded.website, email = excluded.email, phone = excluded.phone, instagram = excluded.instagram, image_url = excluded.image_url, free_consultation = excluded.free_consultation, sports = excluded.sports, source = excluded.source, source_url = excluded.source_url, source_licence = excluded.source_licence, last_verified_at = excluded.last_verified_at, is_sample = excluded.is_sample
  where public.trainers.claimed_by is null and public.trainers.status <> 'removed';
delete from public.trainer_styles where trainer_id = (select id from public.trainers where slug = 'sculpt-yoga-and-pilates-barnsley' and claimed_by is null);
delete from public.trainer_goals where trainer_id = (select id from public.trainers where slug = 'sculpt-yoga-and-pilates-barnsley' and claimed_by is null);
insert into public.trainer_styles (trainer_id, style_slug) select id, s from public.trainers, unnest(array['pilates', 'yoga']::text[]) s where slug = 'sculpt-yoga-and-pilates-barnsley' and claimed_by is null and status = 'published' on conflict do nothing;
insert into public.trainer_goals (trainer_id, goal_slug) select id, g from public.trainers, unnest(array['flexibility', 'older-adults', 'general-fitness']::text[]) g where slug = 'sculpt-yoga-and-pilates-barnsley' and claimed_by is null and status = 'published' on conflict do nothing;

commit;

select count(*) as real_trainers from public.trainers where is_sample = false and status = 'published';
